  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, NULL)
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
