    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
    ELSE COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
  END::text), '')
  END AS st,
            (
    CASE
      WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN (
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  )
      WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN (
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  )
      ELSE ((
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  ) OR (
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  ))
    END
  ) AS row_open
          FROM sap_processed_data spd
          WHERE spd.contract_number = c.contract_id
            
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            AND (
              (
    
  NULLIF(TRIM(COALESCE(
    spd.sto_number::text,
    spd.data->'raw'->>'STO No.',
    spd.data->'raw'->>'STO Number',
    spd.data->'raw'->>'STO No',
    spd.data->'shipment'->>'sto_no',
    spd.data->'contract'->>'sto_no'
  )), '')
 IS NOT NULL
    AND TRIM((
  NULLIF(TRIM(COALESCE(
    spd.sto_number::text,
    spd.data->'raw'->>'STO No.',
    spd.data->'raw'->>'STO Number',
    spd.data->'raw'->>'STO No',
    spd.data->'shipment'->>'sto_no',
    spd.data->'contract'->>'sto_no'
  )), '')
)::text) !~ '^(OP-|MNL-|MSEA-)'
  )
              OR NOT EXISTS (
                SELECT 1
                FROM sap_processed_data spd_gr
                WHERE spd_gr.contract_number = c.contract_id
                  
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_gr.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_gr.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
                  AND spd_gr.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
                  AND (
    
  NULLIF(TRIM(COALESCE(
    spd_gr.sto_number::text,
    spd_gr.data->'raw'->>'STO No.',
    spd_gr.data->'raw'->>'STO Number',
    spd_gr.data->'raw'->>'STO No',
    spd_gr.data->'shipment'->>'sto_no',
    spd_gr.data->'contract'->>'sto_no'
  )), '')
 IS NOT NULL
    AND TRIM((
  NULLIF(TRIM(COALESCE(
    spd_gr.sto_number::text,
    spd_gr.data->'raw'->>'STO No.',
    spd_gr.data->'raw'->>'STO Number',
    spd_gr.data->'raw'->>'STO No',
    spd_gr.data->'shipment'->>'sto_no',
    spd_gr.data->'contract'->>'sto_no'
  )), '')
)::text) !~ '^(OP-|MNL-|MSEA-)'
  )
                  AND NULLIF(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_po_status,
    spd_gr.contract_delete_po_status,
    spd_gr.shipment_delete_po_status,
    spd_gr.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_po_status,
    spd_gr.contract_gr_po_status,
    spd_gr.root_gr_po_status
  )), '')
  END, NULL)
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_sto_status,
    spd_gr.contract_delete_sto_status,
    spd_gr.shipment_delete_sto_status,
    spd_gr.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_sto_status,
    spd_gr.contract_gr_sto_status,
    spd_gr.root_gr_sto_status
  )), '')
  END, NULL)
    ELSE COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_po_status,
    spd_gr.contract_delete_po_status,
    spd_gr.shipment_delete_po_status,
    spd_gr.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_po_status,
    spd_gr.contract_gr_po_status,
    spd_gr.root_gr_po_status
  )), '')
  END, CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_sto_status,
    spd_gr.contract_delete_sto_status,
    spd_gr.shipment_delete_sto_status,
    spd_gr.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_sto_status,
    spd_gr.contract_gr_sto_status,
    spd_gr.root_gr_sto_status
  )), '')
  END, NULL)
  END, '')), '') IS NOT NULL
              )
            )AND (
      UPPER(TRIM(COALESCE(c.incoterm, ''))) <> 'FOB'
      OR (
    
  UPPER(TRIM(COALESCE(
    spd.data->'raw'->>'STO Type',
    spd.data->'raw'->>'STO Type ',
    spd.data->'contract'->>'sto_type',
    spd.data->'shipment'->>'sto_type',
    ''
  )))
 = 'V'
    OR (
      
  UPPER(TRIM(COALESCE(
    spd.data->'raw'->>'STO Type',
    spd.data->'raw'->>'STO Type ',
    spd.data->'contract'->>'sto_type',
    spd.data->'shipment'->>'sto_type',
    ''
  )))
 IS DISTINCT FROM 'T'
      AND 
  UPPER(TRIM(COALESCE(
    spd.data->'raw'->>'STO Type',
    spd.data->'raw'->>'STO Type ',
    spd.data->'contract'->>'sto_type',
    spd.data->'shipment'->>'sto_type',
    ''
  )))
 <> 'V'
      AND NULLIF(TRIM(COALESCE(
    spd.data->'shipment'->>'vessel_name',
    spd.data->'vessel'->>'vessel_name',
    spd.data->'raw'->>'Vessel Name',
    spd.data->'raw'->>'Vessel',
    spd.data->'raw'->>'vessel name'
  )), '') IS NOT NULL
    )
  )
    )
            AND spd.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
            AND NOT (NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL)
        ) s
        WHERE NULLIF(TRIM(COALESCE(s.st, '')), '') IS NOT NULL
          OR s.row_open
      ),
      CASE
        WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB')
        THEN (
    SELECT NULLIF(TRIM(m.child_gr_sto_status), '')
    FROM b2b_ending_child_snapshot m
    WHERE m.origin_po = NULLIF(TRIM((c.po_number)::text), '')
  )
        ELSE NULL
      END,
      CASE
        WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN NULL
        ELSE CASE
    WHEN UPPER(TRIM(COALESCE(c.status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(c.status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(c.status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(c.status::text), '')
  END
      END
    )), ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE')
    OR UPPER(TRIM(COALESCE((COALESCE(
      
      CASE
        WHEN EXISTS (
          SELECT 1
          FROM sap_processed_data spd_del
          WHERE spd_del.contract_number = c.contract_id
            
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_del.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_del.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            AND NULLIF(TRIM(COALESCE(
    spd_del.raw_delete_po_status,
    spd_del.contract_delete_po_status,
    spd_del.shipment_delete_po_status,
    spd_del.root_delete_po_status
  )), '') IS NOT NULL
        ) THEN 'Cancelled'
        WHEN (
          EXISTS (
            SELECT 1
            FROM sap_processed_data spd_any
            WHERE spd_any.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_any.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_any.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
              AND spd_any.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
              AND (
    
  NULLIF(TRIM(COALESCE(
    spd_any.sto_number::text,
    spd_any.data->'raw'->>'STO No.',
    spd_any.data->'raw'->>'STO Number',
    spd_any.data->'raw'->>'STO No',
    spd_any.data->'shipment'->>'sto_no',
    spd_any.data->'contract'->>'sto_no'
  )), '')
 IS NOT NULL
    AND TRIM((
  NULLIF(TRIM(COALESCE(
    spd_any.sto_number::text,
    spd_any.data->'raw'->>'STO No.',
    spd_any.data->'raw'->>'STO Number',
    spd_any.data->'raw'->>'STO No',
    spd_any.data->'shipment'->>'sto_no',
    spd_any.data->'contract'->>'sto_no'
  )), '')
)::text) !~ '^(OP-|MNL-|MSEA-)'
  )
          )
          AND NOT EXISTS (
            SELECT 1
            FROM sap_processed_data spd_live
            WHERE spd_live.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_live.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_live.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
              AND spd_live.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
              AND (
    
  NULLIF(TRIM(COALESCE(
    spd_live.sto_number::text,
    spd_live.data->'raw'->>'STO No.',
    spd_live.data->'raw'->>'STO Number',
    spd_live.data->'raw'->>'STO No',
    spd_live.data->'shipment'->>'sto_no',
    spd_live.data->'contract'->>'sto_no'
  )), '')
 IS NOT NULL
    AND TRIM((
  NULLIF(TRIM(COALESCE(
    spd_live.sto_number::text,
    spd_live.data->'raw'->>'STO No.',
    spd_live.data->'raw'->>'STO Number',
    spd_live.data->'raw'->>'STO No',
    spd_live.data->'shipment'->>'sto_no',
    spd_live.data->'contract'->>'sto_no'
  )), '')
)::text) !~ '^(OP-|MNL-|MSEA-)'
  )
              AND NOT (NULLIF(TRIM(COALESCE(
    spd_live.raw_delete_sto_status,
    spd_live.contract_delete_sto_status,
    spd_live.shipment_delete_sto_status,
    spd_live.root_delete_sto_status
  )), '') IS NOT NULL)
          )
        ) THEN 'Cancelled'
        WHEN (
          NOT EXISTS (
            SELECT 1
            FROM sap_processed_data spd_any
            WHERE spd_any.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_any.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_any.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
              AND spd_any.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
              AND (
    
  NULLIF(TRIM(COALESCE(
    spd_any.sto_number::text,
    spd_any.data->'raw'->>'STO No.',
    spd_any.data->'raw'->>'STO Number',
    spd_any.data->'raw'->>'STO No',
    spd_any.data->'shipment'->>'sto_no',
    spd_any.data->'contract'->>'sto_no'
  )), '')
 IS NOT NULL
    AND TRIM((
  NULLIF(TRIM(COALESCE(
    spd_any.sto_number::text,
    spd_any.data->'raw'->>'STO No.',
    spd_any.data->'raw'->>'STO Number',
    spd_any.data->'raw'->>'STO No',
    spd_any.data->'shipment'->>'sto_no',
    spd_any.data->'contract'->>'sto_no'
  )), '')
)::text) !~ '^(OP-|MNL-|MSEA-)'
  )
          )
          AND EXISTS (
            SELECT 1
            FROM sap_processed_data spd_del
            WHERE spd_del.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_del.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_del.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
              AND spd_del.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
              AND NULLIF(TRIM(COALESCE(
    spd_del.raw_delete_sto_status,
    spd_del.contract_delete_sto_status,
    spd_del.shipment_delete_sto_status,
    spd_del.root_delete_sto_status
  )), '') IS NOT NULL
          )
        ) THEN 'Cancelled'
        ELSE NULL
      END,
      (
        SELECT CASE
          WHEN BOOL_OR(s.row_open) OR BOOL_OR(UPPER(TRIM(COALESCE(s.st, ''))) IN ('OPEN', 'ACTIVE')) THEN 'Open'
          WHEN BOOL_OR(UPPER(TRIM(COALESCE(s.st, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE')) THEN 'Close'
          WHEN BOOL_OR(UPPER(TRIM(COALESCE(s.st, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL')) THEN 'Cancelled'
          ELSE NULL
        END
        FROM (
          SELECT
            CASE
    WHEN UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, NULL)
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
    ELSE COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
  END, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, NULL)
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
    ELSE COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
  END, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, NULL)
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
    ELSE COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
  END, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(CASE
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, NULL)
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
    ELSE COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_po_status,
    spd.contract_delete_po_status,
    spd.shipment_delete_po_status,
    spd.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_po_status,
    spd.contract_gr_po_status,
    spd.root_gr_po_status
  )), '')
  END, CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd.raw_gr_sto_status,
    spd.contract_gr_sto_status,
    spd.root_gr_sto_status
  )), '')
  END, NULL)
  END::text), '')
  END AS st,
            (
    CASE
      WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN (
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  )
      WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN (
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  )
      ELSE ((
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_sto_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_sto_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  ) OR (
    UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.raw_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.raw_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
    OR UPPER(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(spd.contract_gr_po_status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(spd.contract_gr_po_status::text), '')
  END, ''))) IN ('OPEN', 'ACTIVE')
  ))
    END
  ) AS row_open
          FROM sap_processed_data spd
          WHERE spd.contract_number = c.contract_id
            
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            AND (
              (
    
  NULLIF(TRIM(COALESCE(
    spd.sto_number::text,
    spd.data->'raw'->>'STO No.',
    spd.data->'raw'->>'STO Number',
    spd.data->'raw'->>'STO No',
    spd.data->'shipment'->>'sto_no',
    spd.data->'contract'->>'sto_no'
  )), '')
 IS NOT NULL
    AND TRIM((
  NULLIF(TRIM(COALESCE(
    spd.sto_number::text,
    spd.data->'raw'->>'STO No.',
    spd.data->'raw'->>'STO Number',
    spd.data->'raw'->>'STO No',
    spd.data->'shipment'->>'sto_no',
    spd.data->'contract'->>'sto_no'
  )), '')
)::text) !~ '^(OP-|MNL-|MSEA-)'
  )
              OR NOT EXISTS (
                SELECT 1
                FROM sap_processed_data spd_gr
                WHERE spd_gr.contract_number = c.contract_id
                  
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_gr.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_gr.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
                  AND spd_gr.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
                  AND (
    
  NULLIF(TRIM(COALESCE(
    spd_gr.sto_number::text,
    spd_gr.data->'raw'->>'STO No.',
    spd_gr.data->'raw'->>'STO Number',
    spd_gr.data->'raw'->>'STO No',
    spd_gr.data->'shipment'->>'sto_no',
    spd_gr.data->'contract'->>'sto_no'
  )), '')
 IS NOT NULL
    AND TRIM((
  NULLIF(TRIM(COALESCE(
    spd_gr.sto_number::text,
    spd_gr.data->'raw'->>'STO No.',
    spd_gr.data->'raw'->>'STO Number',
    spd_gr.data->'raw'->>'STO No',
    spd_gr.data->'shipment'->>'sto_no',
    spd_gr.data->'contract'->>'sto_no'
  )), '')
)::text) !~ '^(OP-|MNL-|MSEA-)'
  )
                  AND NULLIF(TRIM(COALESCE(CASE
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('FRC', 'CIF', 'CFR') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_po_status,
    spd_gr.contract_delete_po_status,
    spd_gr.shipment_delete_po_status,
    spd_gr.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_po_status,
    spd_gr.contract_gr_po_status,
    spd_gr.root_gr_po_status
  )), '')
  END, NULL)
    WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_sto_status,
    spd_gr.contract_delete_sto_status,
    spd_gr.shipment_delete_sto_status,
    spd_gr.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_sto_status,
    spd_gr.contract_gr_sto_status,
    spd_gr.root_gr_sto_status
  )), '')
  END, NULL)
    ELSE COALESCE(CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_po_status,
    spd_gr.contract_delete_po_status,
    spd_gr.shipment_delete_po_status,
    spd_gr.root_delete_po_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_po_status,
    spd_gr.contract_gr_po_status,
    spd_gr.root_gr_po_status
  )), '')
  END, CASE
    WHEN NULLIF(TRIM(COALESCE(
    spd_gr.raw_delete_sto_status,
    spd_gr.contract_delete_sto_status,
    spd_gr.shipment_delete_sto_status,
    spd_gr.root_delete_sto_status
  )), '') IS NOT NULL THEN 'Cancelled'
    ELSE NULLIF(TRIM(COALESCE(
    spd_gr.raw_gr_sto_status,
    spd_gr.contract_gr_sto_status,
    spd_gr.root_gr_sto_status
  )), '')
  END, NULL)
  END, '')), '') IS NOT NULL
              )
            )
            AND spd.import_id IS NOT DISTINCT FROM (
            SELECT spd_li.import_id
            FROM sap_processed_data spd_li
            WHERE spd_li.contract_number = c.contract_id
              
            AND (
              NULLIF(TRIM(COALESCE(c.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') IS NULL
              OR NULLIF(TRIM(COALESCE(spd_li.po_number::text, '')), '') = NULLIF(TRIM(COALESCE(c.po_number::text, '')), '')
            )
            ORDER BY spd_li.created_at DESC NULLS LAST
            LIMIT 1
          )
            AND NOT (NULLIF(TRIM(COALESCE(
    spd.raw_delete_sto_status,
    spd.contract_delete_sto_status,
    spd.shipment_delete_sto_status,
    spd.root_delete_sto_status
  )), '') IS NOT NULL)
        ) s
        WHERE NULLIF(TRIM(COALESCE(s.st, '')), '') IS NOT NULL
          OR s.row_open
      ),
      CASE
        WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB')
        THEN (
    SELECT NULLIF(TRIM(m.child_gr_sto_status), '')
    FROM b2b_ending_child_snapshot m
    WHERE m.origin_po = NULLIF(TRIM((c.po_number)::text), '')
  )
        ELSE NULL
      END,
      CASE
        WHEN UPPER(TRIM(COALESCE(c.incoterm, ''))) IN ('LCO', 'FOB') THEN NULL
        ELSE CASE
    WHEN UPPER(TRIM(COALESCE(c.status, ''))) IN ('ACTIVE', 'OPEN') THEN 'Open'
    WHEN UPPER(TRIM(COALESCE(c.status, ''))) IN ('CLOSE', 'CLOSED', 'COMPLETED', 'COMPLETE') THEN 'Close'
    WHEN UPPER(TRIM(COALESCE(c.status, ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL') THEN 'Cancelled'
    ELSE NULLIF(TRIM(c.status::text), '')
  END
      END
    )), ''))) IN ('CANCELLED', 'CANCELED', 'CANCEL')
  )                           AS blocked_by_gr_status
FROM contracts c
WHERE TRIM(c.po_number::text) = TRIM(:'po') OR TRIM(c.contract_id::text) = TRIM(:'po');

\echo '=== 4. STO rows ==='
SELECT cs.sto_number, cs.sto_type, cs.updated_at
FROM contract_stos cs
JOIN contracts c ON c.id = cs.contract_id
WHERE TRIM(c.po_number::text) = TRIM(:'po') OR TRIM(c.contract_id::text) = TRIM(:'po')
ORDER BY cs.sto_number;

\echo '=== 5. latest SAP row for this PO ==='
SELECT
  spd.contract_number,
  spd.created_at,
  spd.data->'raw'->>'Incoterm'                 AS raw_incoterm,
  spd.data->'raw'->>'STO Type'                 AS raw_sto_type,
  spd.data->'raw'->>'STO No.'                  AS raw_sto_no,
  spd.data->'raw'->>'B2B Flag'                 AS raw_b2b_flag,
  spd.data->'raw'->>'Contract Reference PO'    AS raw_contract_ref_po,
  spd.data->'raw'->>'Discharge Destination'    AS raw_discharge_destination
FROM sap_processed_data spd
WHERE TRIM(spd.contract_number) IN (
  SELECT TRIM(c.contract_id::text) FROM contracts c
  WHERE TRIM(c.po_number::text) = TRIM(:'po') OR TRIM(c.contract_id::text) = TRIM(:'po')
)
ORDER BY spd.created_at DESC
LIMIT 3;

\echo '=== 6. snapshot freshness (can hide a row on status-filtered views only) ==='
SELECT module, is_stale, refreshed_at, row_count FROM pipeline_summary_refresh_meta ORDER BY module;
SELECT 'contract_latest_spd' AS meta, is_stale, refreshed_at FROM contract_latest_spd_snapshot_meta WHERE id = 'global';

\echo '=== 7. how many contracts share this PO number ==='
SELECT COUNT(*)::int AS contracts_with_this_po
FROM contracts c
WHERE TRIM(c.po_number::text) = TRIM(:'po');
